// --- Level 7 专属敌人覆盖表 (2026-11-05) ---
// 用法：按敌人类型填要覆盖的属性，L7 里自动生效，其他关卡完全不受影响。
// 类型键：'guard' 普通守卫 / 'observer' 观察者 / 'jammer' 干扰者
// 示例：guard: { hp: 150, maxHp: 150, patrolSpeed: 1.5 }  // 只改 L7 守卫的血量和速度
// 注意：绝不直接改 spawnWave() 里的敌人初始值（会污染所有关卡）。
// 全新敌人类型（新 AI 行为）：不要在这里加，先在 DEV_NOTES.md 记录 012 里登记设计，
// 再在 engine.js 里加独立的 drawAgentL7 / 行为分支，不要动原有敌人逻辑。
const LEVEL7_ENEMY_OVERRIDES = {
    // 现在是空的，L7 敌人 = 原版数值。以后要改 L7 敌人只填这里。
    // guard: {},
    // observer: {},
    // jammer: {},
};

// L7 敌人覆盖应用函数：在 spawnWave() 里每个敌人创建后调用
function applyLevel7EnemyOverrides(enemy) {
    if (!enemy) return enemy;
    const levelId = (typeof getCurrentLevelId === 'function') ? getCurrentLevelId() : '';
    if (levelId !== 'level7_lab') return enemy;
    const type = enemy.isJammer ? 'jammer' : (enemy.isObserver ? 'observer' : 'guard');
    const override = LEVEL7_ENEMY_OVERRIDES[type];
    if (override) Object.assign(enemy, override);
    return enemy;
}

// --- Level 7 专属武器覆盖表 (2026-11-05) ---
// 用法：在这里填武器 id → 要覆盖的属性，L7 里自动生效，其他关卡完全不受影响。
// 示例：RIFLE: { damage: 35, cooldown: 8 }  // 只改 L7 的步枪伤害和射速
// 注意：绝不直接改上面的 WEAPONS 全局对象（会污染所有关卡）。
const LEVEL7_WEAPON_OVERRIDES = {
    // 实验 v5：L7/L8 的 3 号位是 GEN-12 霰弹枪，用三管猎枪数值做底（伤害 32x12、冷却 35f、射程 380）
    3: { damage: 32, pellets: 12, spread: 0.28, speed: 20, radius: 3.8, range: 380, cooldown: 35, type: 'shotgun' },
};

// 关卡专有武器动态属性适配器 (仅在 Level 0 大地图生效，绝不波及其他关卡)
// 实验：L7/L8 有限弹药系统（2026-11-06 v4）：弹匣容量 + 有限总弹药，弹匣打空从总弹药补，总弹药为 0 则无法开火
const L78_MAG_SIZE = { 1: 30, 2: 15, 3: 6, 4: 5, 5: 1 };
const L78_RESERVE_INIT = { 1: 120, 2: 60, 3: 30, 4: 20, 5: 5 };
const __l78Ammo = {}; // { weaponId: { mag, reserve } }
let lastAltarHintTime = 0; // 2026-11-07：祭坛外击杀提示节流（8 秒内只提示一次）
function __l78AmmoGet(id) {
    if (!__l78Ammo[id]) {
        __l78Ammo[id] = { mag: (L78_MAG_SIZE[id] || 30), reserve: (L78_RESERVE_INIT[id] !== undefined ? L78_RESERVE_INIT[id] : 0) };
    }
    return __l78Ammo[id];
}
// 实验：L7/L8 自动换弹（2026-11-06 v11）：弹匣打空后进入 90 帧（1.5 秒）换弹，期间不能开火
const L78_RELOAD_FRAMES = 90; // 所有武器统一 1.5 秒
let __l78Reloading = false;   // 是否正在换弹
let __l78ReloadTimer = 0;     // 换弹计时（帧）
let __l78ReloadWeaponId = 0;  // 正在换弹的武器 id
function __l78StartReload(id) {
    const a = __l78AmmoGet(id);
    if (a.reserve <= 0) return false; // 总弹药为 0，不进换弹
    __l78Reloading = true;
    __l78ReloadTimer = 0;
    __l78ReloadWeaponId = id;
    if (typeof soundManager !== 'undefined' && soundManager.playReload) soundManager.playReload();
    return true;
}
function __l78CancelReload() {
    __l78Reloading = false;
    __l78ReloadTimer = 0;
    __l78ReloadWeaponId = 0;
}
function __l78TickReload() {
    if (!__l78Reloading) return;
    __l78ReloadTimer++;
    if (__l78ReloadTimer >= L78_RELOAD_FRAMES) {
        const a = __l78AmmoGet(__l78ReloadWeaponId);
        const need = (L78_MAG_SIZE[__l78ReloadWeaponId] || 30);
        const refill = Math.min(need, a.reserve);
        a.reserve -= refill;
        a.mag = refill;
        __l78Reloading = false;
        __l78ReloadTimer = 0;
        __l78ReloadWeaponId = 0;
        if (typeof addLog === 'function') addLog("弹匣已更换");
    }
}
// 开火扣弹：返回 true=成功扣弹可开火，false=无弹无法开火
function __l78AmmoConsume(id) {
    if (__l78Reloading) return false; // 换弹中不能开火
    const a = __l78AmmoGet(id);
    if (a.mag > 0) { a.mag--; return true; }
    // 弹匣空：总弹药 > 0 则开始换弹（不再瞬间补满）
    if (a.reserve > 0) {
        __l78StartReload(id);
        return false;
    }
    return false;
}
// 实验：L7/L8 步枪快慢机（2026-11-06 v4）：false=半自动（步枪原值），true=全自动（冲锋枪数值）
window.__l7RifleAutoMode = false;

function getEffectiveWeapon(wp) {
    if (!wp) return wp;
    const levelId = (typeof getCurrentLevelId === 'function') ? getCurrentLevelId() : '';

    // Level 7/8：查专属覆盖表，有就返回修改后的副本，没有就返回原样
    if (levelId === 'level7_lab' || levelId === 'level8_test') {
        // 实验：步枪快慢机——全自动状态用冲锋枪数值（伤害 16、冷却 6f、射程 380）
        if (wp.id === 1 && window.__l7RifleAutoMode) {
            return { ...wp, damage: 16, cooldown: 6, range: 380 };
        }
        const override = LEVEL7_WEAPON_OVERRIDES[wp.id];
        if (override) return { ...wp, ...override };
        return wp;
    }

    const isLevel0 = (levelId === 'level0_test');
    if (!isLevel0) return wp;

    switch(wp.id) {
        case 1:  return { ...wp, range: 920, cooldown: 7,  damage: 28, speed: 20 };
        case 2:  return { ...wp, range: 720, cooldown: 8,  damage: 34, speed: 20 };
        case 3:  return { ...wp, range: 620, cooldown: 4,  damage: 16, speed: 22 };
        case 4:  return { ...wp, range: 1600,cooldown: 36, damage: 140,speed: 32 };
        case 5:  return { ...wp, range: 600, cooldown: 50, damage: 130,speed: 12, blastRadius: 130 };
        case 6:  return { ...wp, range: 1200,cooldown: 5,  damage: 42, speed: 23 };
        case 7:  return { ...wp, range: 2500,cooldown: 18, damage: 99999,speed:32, blastRadius: 190 };
        case 8:  return { ...wp, range: 720, cooldown: 25, damage: 52, pellets: 3, speed: 24, radius: 5.6 };
        case 9:  return { ...wp, range: 640, cooldown: 30, damage: 44, speed: 18, radius: 16 };
        case 10: return { ...wp, range: 640, cooldown: 50, damage: 170, radius: 105 }; // 2026-11-01：射程 1000→640，与光镰持平
        case 11: return { ...wp, range: 680, cooldown: 5,  damage: 26, speed: 25, radius: 8 };
        default: return wp;
    }
}

let currentWeapon = WEAPONS.RIFLE;
let unlockedWeapons = [WEAPONS.RIFLE.id];

function isKillstreakSupportedLevel(levelId) {
    if (levelId === 'level0_test') return false;
    return true;
}

// 连杀奖励机制专有变量 (在 level0_test 与 level1_airport 关卡测试生效，绝不影响 level2/3/4)
let level0StreakCount = 0;
let level0MgAmmo = 0;
let level0MgFirstUseDone = false;
let level0UavAmmo = 0;
let level0UavFirstUseDone = false;
let level0InfiniteBlindTimer = 0;
let level0InfiniteBlindActiveLast = false;
let level0InfiniteBlindPaused = false;

function settleAllPendingDamage() {
    let totalSettled = 0;
    if (typeof enemies !== 'undefined' && Array.isArray(enemies)) {
        enemies.forEach(e => {
            if (e.pendingDamage > 0) {
                applyDamageToEnemy(e, e.pendingDamage);
                e.pendingDamage = 0;
                e.pendingDamageInAltar = false;
                e.hitTimer = 8;
                const isDemon = e.isDemon || (getCurrentLevelId() === 'level0_test');
                createExplosion(e.x, e.y, 20, isDemon ? '#ff2200' : '#00FF66');
                totalSettled++;
            }
        });
    }
    return totalSettled;
}

function pauseInfiniteBlindZone() {
    blindActive = false;
    blindZone = null;
    level0InfiniteBlindPaused = true;
    level0InfiniteBlindActiveLast = false;
    if (typeof soundManager !== 'undefined') {
        soundManager.stopBlindZone();
    }
    
    // 盲区暂停时，立刻结算盲区内积累的所有延迟伤害 (pendingDamage)
    let totalSettled = settleAllPendingDamage();

    if (typeof addLog === 'function') {
        const secLeft = (level0InfiniteBlindTimer / 60).toFixed(1);
        if (totalSettled > 0) {
            addLog(`⚡ [全图盲区暂停/结算] 剩余 ${secLeft}s，结算盲区延迟伤害 (${totalSettled} 个敌人)`);
        } else {
            addLog(`⏸ [全图盲区已暂停] 剩余 ${secLeft}s (按 Space 或 8 键可随时重新开启)`);
        }
    }
}

function resumeInfiniteBlindZone() {
    blindActive = true;
    blindEnergy = MAX_BLIND_ENERGY;
    blindZone = { x: player.x, y: player.y, radius: 4000 };
    level0InfiniteBlindPaused = false;
    if (level0StreakCount >= 7) {
        level0StreakCount = 0;
        if (typeof addLog === 'function') addLog("⚡ [连杀数重置] 全图盲区开启，连杀数归零");
    }
    if (typeof soundManager !== 'undefined') {
        soundManager.playBlindZone();
    }
    if (typeof addLog === 'function') {
        const secLeft = (level0InfiniteBlindTimer / 60).toFixed(1);
        addLog(`⚡ [全图盲区已手动开启] 剩余 ${secLeft}s`);
    }
}

function activateLevel0KillstreakReward(num) {
    const currentLevelId = getCurrentLevelId();
    if (!isKillstreakSupportedLevel(currentLevelId)) return;

    if (num === 1) {
        // 机枪 (3 连杀) -> 30 发子弹
        if (level0StreakCount >= 3 || level0MgAmmo > 0) {
            if (!unlockedWeapons.includes(WEAPONS.MACHINE_GUN.id)) {
                unlockedWeapons.push(WEAPONS.MACHINE_GUN.id);
            }
            if (currentWeapon.id === WEAPONS.MACHINE_GUN.id) {
                if (level0StreakCount >= 3 && level0MgFirstUseDone) {
                    level0MgAmmo += 30;
                    level0MgFirstUseDone = false;
                    if (typeof addLog === 'function') addLog(`⚡ [再次解锁连杀] 补充 30 发机枪弹药！(当前弹药: ${level0MgAmmo})`);
                    createExplosion(player.x, player.y, 18, '#FF9900');
                } else {
                    if (typeof addLog === 'function') addLog(`机枪装备中 (当前弹药: ${level0MgAmmo})`);
                }
            } else {
                if (level0MgAmmo <= 0 && level0StreakCount >= 3) {
                    level0MgAmmo = 30;
                    level0MgFirstUseDone = false;
                    if (typeof addLog === 'function') addLog("⚡ 已装备 [机枪] (30发子弹)。首次开火时将重置连杀数");
                } else if (level0MgAmmo > 0 && level0StreakCount >= 3 && level0MgFirstUseDone) {
                    level0MgAmmo += 30;
                    level0MgFirstUseDone = false;
                    if (typeof addLog === 'function') addLog(`⚡ 再次达到 3 连杀！装备机枪并补充 30 发子弹 (当前: ${level0MgAmmo})`);
                } else {
                    if (typeof addLog === 'function') addLog(`装备机枪 (剩余弹药: ${level0MgAmmo})`);
                }
                switchWeapon(WEAPONS.MACHINE_GUN);
                createExplosion(player.x, player.y, 18, '#FF9900');
            }
        } else {
            if (typeof addLog === 'function') addLog(`❌ [机枪] 未解锁！需 3 连杀 (当前: ${level0StreakCount}/3)`);
        }
    } else if (num === 2) {
        // UAV 打击 (5 连杀) -> 5 次爆破打击
        if (level0StreakCount >= 5 || level0UavAmmo > 0) {
            if (!unlockedWeapons.includes(WEAPONS.UAV.id)) {
                unlockedWeapons.push(WEAPONS.UAV.id);
            }
            if (currentWeapon.id === WEAPONS.UAV.id) {
                if (level0StreakCount >= 5 && level0UavFirstUseDone) {
                    level0UavAmmo += 5;
                    level0UavFirstUseDone = false;
                    if (typeof addLog === 'function') addLog(`⚡ [再次解锁连杀] 补充 5 次 UAV 爆破打击！(当前次数: ${level0UavAmmo})`);
                    createExplosion(player.x, player.y, 22, '#00E5FF');
                } else {
                    if (typeof addLog === 'function') addLog(`UAV 打击准备中 (当前剩余: ${level0UavAmmo} 次)`);
                }
            } else {
                if (level0UavAmmo <= 0 && level0StreakCount >= 5) {
                    level0UavAmmo = 5;
                    level0UavFirstUseDone = false;
                    if (typeof addLog === 'function') addLog("⚡ 已装备 [UAV打击] (5次爆破)。首次打击时将重置连杀数");
                } else if (level0UavAmmo > 0 && level0StreakCount >= 5 && level0UavFirstUseDone) {
                    level0UavAmmo += 5;
                    level0UavFirstUseDone = false;
                    if (typeof addLog === 'function') addLog(`⚡ 再次达到 5 连杀！装备 UAV 并补充 5 次爆破打击 (当前: ${level0UavAmmo})`);
                } else {
                    if (typeof addLog === 'function') addLog(`装备 UAV打击 (剩余次数: ${level0UavAmmo})`);
                }
                switchWeapon(WEAPONS.UAV);
                createExplosion(player.x, player.y, 22, '#00E5FF');
            }
        } else {
            if (typeof addLog === 'function') addLog(`❌ [UAV打击] 未解锁！需 5 连杀 (当前: ${level0StreakCount}/5)`);
        }
    } else if (num === 3) {
        // 全图无限盲区 (7 连杀) -> 选中仅就绪，开启需手动操作 (开启时才扣除连杀数)
        if (level0InfiniteBlindTimer > 0) {
            if (level0StreakCount >= 7) {
                level0InfiniteBlindTimer = 420; // 刷新 7 秒
                level0InfiniteBlindPaused = true;
                blindActive = false;
                if (typeof addLog === 'function') addLog("⚡ 再次达到 7 连杀！刷新 [全图无限盲区] 预备时间为 7 秒！(按 Space 键或 8 键开启)");
                createExplosion(player.x, player.y, 28, '#E024FF');
            } else {
                if (blindActive) {
                    pauseInfiniteBlindZone();
                } else {
                    resumeInfiniteBlindZone();
                }
            }
        } else if (level0StreakCount >= 7) {
            level0InfiniteBlindTimer = 420; // 7秒 (420帧)
            level0InfiniteBlindPaused = true;
            blindActive = false;
            if (typeof addLog === 'function') addLog("⚡ 已选中 [全图无限盲区] (7秒就绪)！(按 Space 键或 8 键手动开启)");
            createExplosion(player.x, player.y, 28, '#E024FF');
        } else {
            if (typeof addLog === 'function') addLog(`❌ [全图无限盲区] 未解锁！需 7 连杀 (当前: ${level0StreakCount}/7)`);
        }
    }
}

