            ctx.roundRect(p.x + 5, p.y + 5, p.w - 10, p.h - 10, 4);
            ctx.fill();
            ctx.strokeStyle = '#38bdf8';
            ctx.lineWidth = 1.2;
            ctx.stroke();

            // Side Support Wings
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(p.x + 3, cy - 8, 3, 16);
