            ctx.fillStyle = '#84cc16';
            ctx.beginPath(); ctx.arc(boardX + 11, boardY + 9, 2, 0, Math.PI * 2); ctx.fill();

            // 6. Stack of Fine Blue-Pattern Porcelain Dishes (青花餐盘叠放)
            const plateX = p.x + 58;
