            // Cushion Gradient (墨绿丝绒垫)
            const leftCushGrad = ctx.createLinearGradient(leftChairX + 3, leftChairY, leftChairX + chairW, leftChairY);
            leftCushGrad.addColorStop(0, '#052e16');
