            ctx.fillRect(leftChairX + 0.5, leftChairY + chairH - 2.5, 1.5, 1.5);

            // 2. Right Chair (右侧独立豪华墨绿绒面卡座 [ ])
            const rightChairX = p.x + p.w - chairW;
