            // Wood Frame (East edge) & Deep Emerald Velvet Cushion (facing West)
            ctx.fillStyle = '#2b1810'; // 暗红木雕花靠背
            ctx.fillRect(rightChairX + chairW - 3, rightChairY, 3, chairH);

