                const barGrad = ctx.createLinearGradient(p.x, p.y, p.x, p.y + barH);
                barGrad.addColorStop(0, '#1e293b');
                barGrad.addColorStop(0.5, '#0f172a');
                barGrad.addColorStop(1, '#020617');
