                    ctx.fillStyle = '#0284c7';
                    ctx.fillRect(posX + 4.5, posY + 7.0, 5, 0.6); // Customer price LED
                    
                    // Touch LCD screen on NORTH side (朝内，正对北侧酒保眼睛)
                    ctx.fillStyle = '#1e293b'; // Screen frame
